<script setup lang="ts">
import { onShow } from '@dcloudio/uni-app'; import { computed } from 'vue'; import BottomNav from '../../components/BottomNav.vue'; import { useLedger } from '../../stores/ledger'; import { yuan } from '../../utils/money'
const ledger=useLedger(); const s=ledger.state; const groups=computed(()=>{const map:Record<string,typeof s.transactions>={}; for(const t of s.transactions){const d=t.occurredAt.slice(0,10); (map[d] ||= []).push(t)} return Object.entries(map).sort((a,b)=>b[0].localeCompare(a[0]))}); const label=(type:string)=>({EXPENSE:'支出',INCOME:'收入',TRANSFER:'转账',REPAYMENT:'还款'}[type]||type); const amount=(t:any)=>t.type==='EXPENSE'?`- ${yuan(t.amountCents)}`:t.type==='INCOME'?`+ ${yuan(t.amountCents)}`:yuan(t.amountCents); function open(id:number){uni.navigateTo({url:`/pages/detail/detail?id=${id}`})}; function newEntry(){uni.navigateTo({url:'/pages/entry/entry'})}; onShow(async()=>{try{if(!s.token)await ledger.login();else await ledger.refresh()}catch{}})
</script>
<template><view class="page"><view class="brand"><image src="/static/brand.png"/><view><text class="brand-name">哈记账</text><text class="brand-sub">记录每一笔，让生活更清晰</text></view></view><view class="card summary"><text class="summary-title">{{new Date().getFullYear()}} 年 {{new Date().getMonth()+1}} 月 · 日均消费</text><text class="summary-value">{{yuan(s.summary?.dailyExpenseCents)}}</text><view class="summary-grid"><view><text class="label">本月支出</text><text class="value expense">{{yuan(s.summary?.expenseCents)}}</text></view><view><text class="label">本月收入</text><text class="value income">{{yuan(s.summary?.incomeCents)}}</text></view></view></view><text class="section-title">最近记账</text><view v-if="!groups.length" class="card empty">暂无记账记录<text>点击右下角 + 添加第一笔记账</text></view><view v-for="group in groups" :key="group[0]"><view class="date-row"><text>{{group[0]}}</text><text>{{group[1].length}} 笔</text></view><button v-for="t in group[1]" :key="t.id" class="transaction" @click="open(t.id)"><text class="transaction-icon">{{t.type==='INCOME'?'收':t.type==='EXPENSE'?'支':t.type==='TRANSFER'?'转':'还'}}</text><view class="transaction-copy"><text class="transaction-title">{{label(t.type)}}</text><text class="transaction-note">{{t.occurredAt.slice(11,16)}} · {{t.note || '无备注'}}</text></view><text :class="['transaction-amount', t.type==='INCOME'?'income':t.type==='EXPENSE'?'expense':'']">{{amount(t)}}</text><text class="arrow">›</text></button></view><button class="fab" @click="newEntry">＋</button><BottomNav active="home"/></view></template>
